head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.pSndNo;
scwin.pMktCd;
scwin.pSndlocCd;
scwin.gLdMktTp = js_market;
scwin.gDate;
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gSndloc = js_sndloc; //송신처구분코드

scwin.vScrenID = 'ULDSTF35006.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    //  기간 from~ to  셋팅	
    edt_SDate.setValue($c.ut.cGetToday("yyyymmdd"));
    edt_EDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

    $c.stf.Combo_CBDataSetPeriod(cmb_PeriodTp);
};
scwin.fn_validCheck = function() {
    // 일자자 체크
    if ($c.stf.getObjectValue(edt_SDate).length < 8) {
        $c.win.alert("일자를 올바르게 입력하십시오.");
        edt_SDate.focus();
        return false;
    }

    // 일자 체크
    if ($c.stf.getObjectValue(edt_EDate).length < 8) {
        $c.win.alert("일자를 올바르게 입력하십시오.");
        edt_EDate.focus();
        return false;
    }
    if ($c.stf.compareFromToDate2(edt_SDate, edt_EDate) == false) {
        return false;
    }
    return true;
};
scwin.fn_Search = function() {
    if (!scwin.fn_validCheck()) return;
    txb_TotalCnt.setValue("총건수 : ");
    var url = "/AtsContactInfo.do?method=listEmContactNoti" + "&FROM_DATE=" + $c.stf.getObjectValue(edt_SDate) + "&TO_DATE=" + $c.stf.getObjectValue(edt_EDate) + "&LD_MKT_TP_CD=" + $c.stf.getObjectValue(rdo_MktTpCd) + "&SNDLOC_TP_CD=" + $c.stf.getObjectValue(rdo_SndLocTpCd) + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

    // 그리드의 데이타 조회
    dts_list.DataID = encodeURI(url);
    dts_list.reset();
    $c.cm.ShowWin(grd_Grid);
};


// 그리드에서 클릭 row의 변수셋팅
scwin.fn_setContnId = function(obj) {
    scwin.pSndNo = dts_list.getCellData(eval(obj), "SND_NO");
    scwin.pMktCd = dts_list.getCellData(eval(obj), "LD_MKT_TP_CD");
    scwin.pSndlocCd = dts_list.getCellData(eval(obj), "SNDLOC_TP_CD");
};
scwin.grd_Grid_OnClick = async function(row, colid) {
    // 클릭된 값 변수에 셋팅
    scwin.fn_setContnId(row);
    if (row >= 1) {
        await $c.frame.CreateDialogFrame("gform", "/dscltrend/ULDSTF35006_POP.gfm", "보낸곳 목록", 200, 100, 630, 240, "window");
    }
};
scwin.btn_Search_onclick = function() {
    scwin.fn_Search();
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);

    //var file_name = "통보내역";
    //var today = cGetToday('yyyymmddhhmmss');
    //var xls_path = getExcelDownPath()+today+"_"+file_name+".xlsx";
    $c.data.downloadGridViewExcel(grd_Grid, "통보내역", "", "8");
};
scwin.img_FromCal_onclick = function() {
    popUpCalendar4(edt_SDate, 1);
};
scwin.img_ToCal_onclick = function() {
    popUpCalendar4(edt_EDate, 2);
};
scwin.edt_SDate_OnLastChar = function(ch) {
    afterPopUpCalendar(1); //if(시작일>종료일) 종료일=시작일;

};
scwin.edt_EDate_OnLastChar = function(ch) {
    afterPopUpCalendar(2); //if(시작일>종료일) 시작일=종료일;

};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_SDate, edt_EDate);
};
scwin.dts_list_OnLoadCompleted = function(rowcount) {
    if (dts_list.errorMsg) {
        $c.win.alert("조회할 수 없습니다. 시스템 관리자에게 문의하세요");
    } else {
        txb_TotalCnt.setValue("총건수 : " + rowcount);
    }
    $c.cm.CloseWin(rowcount, grd_Grid);
};
scwin.dts_list_OnLoadError = function() {
    $c.win.alert("조회할 수 없습니다. 시스템 관리자에게 문의하세요");
    $c.cm.CloseWin('', grd_Grid);
};
scwin.gform_onload = function() {
    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_1);
    $c.stf.showObj(pnl_type, false);
    if (scwin.gLdMktTp == '1' || scwin.gLdMktTp == '2') {
        $c.stf.setObjectValue(rdo_MktTpCd, scwin.gLdMktTp);
        $c.stf.setObjectValue(rdo_SndLocTpCd, scwin.gSndloc);
        $c.cm.setColumnProp(grd_Grid, "LD_MKT_TP_NM", "show", false);
        $c.cm.setColumnProp(grd_Grid, "SNDLOC_TP_NM", "show", false);
    } else {
        $c.stf.showObj(pnl_type, true);
        $c.stf.setObjectValue(rdo_MktTpCd, '9');
        $c.stf.setObjectValue(rdo_SndLocTpCd, 'AA');
        $c.cm.setColumnProp(grd_Grid, "LD_MKT_TP_NM", "show", true);
        $c.cm.setColumnProp(grd_Grid, "SNDLOC_TP_NM", "show", true);
    }
    scwin.fn_SetCode();
    scwin.fn_Search();
};
